import { createElement, useMemo } from "react";

const Badge = ({ label, count }) => {
  const total = useMemo(() => count * 2, [count]);
  return createElement("span", { className: "badge" }, label, " ", total);
};

const Panel = ({ title, children }) =>
  createElement("section", { className: "panel" }, createElement("h2", null, title), children);

export { Badge, Panel };
